insert into public.galerie_images (type_contenu, slug, ordre, nature, url, legende_fr, legende_en, credit, source_url) values
  ('mythe', 'mythe-miengu-esprits-eau-sawa', 3, 'illustration', $q$https://ygkyapryramhaskfbrrt.supabase.co/storage/v1/object/public/heroes-media/images/galerie/mythologie/mythe-miengu-esprits-eau-sawa/03.jpg$q$, $q$Le feu de Moto : au soir de l'épreuve, seul le feu de grosses bûches de Moto brûle encore (mythe bakweri, illustration).$q$, $q$Moto's fire: on the evening of the contest, only Moto's fire of big logs is still burning (Bakweri myth, illustration).$q$, 'Illustration AFROBACK', null),
  ('mythe', 'mythe-ngog-lituba-bassa', 3, 'illustration', $q$https://ygkyapryramhaskfbrrt.supabase.co/storage/v1/object/public/heroes-media/images/galerie/mythologie/mythe-ngog-lituba-bassa/03.jpg$q$, $q$Ki Wom verse l'eau d'une calebasse neuve sur la tête de Mban, sous le regard de Ngog (légende basaa recueillie par J. Mboui, illustration).$q$, $q$Ki Wom pours water from a new calabash over Mban's head, as Ngog looks on (Basaa legend recorded by J. Mboui, illustration).$q$, 'Illustration AFROBACK', null),
  ('mythe', 'mythe-ngog-lituba-bassa', 5, 'illustration', $q$https://ygkyapryramhaskfbrrt.supabase.co/storage/v1/object/public/heroes-media/images/galerie/mythologie/mythe-ngog-lituba-bassa/05.jpg$q$, $q$La troisième porte, Kel, le jour : trois jeunes filles posent leurs gerbes d'herbes sur la tête de Mban (légende basaa, version de J. Mboui, illustration).$q$, $q$The third door, Kel, the day: three young women lay their sheaves of grass on Mban's head (Basaa legend, J. Mboui's version, illustration).$q$, 'Illustration AFROBACK', null),
  ('mythe', 'mythe-ngog-lituba-bassa', 7, 'illustration', $q$https://ygkyapryramhaskfbrrt.supabase.co/storage/v1/object/public/heroes-media/images/galerie/mythologie/mythe-ngog-lituba-bassa/07.jpg$q$, $q$La toile de l'araignée tendue devant la grotte, qui trompa les poursuivants (version populaire de la légende, publiée par Nyoumea en 1978, illustration).$q$, $q$The spider's web stretched across the cave entrance, which fooled the pursuers (popular version of the legend, published by Nyoumea in 1978, illustration).$q$, 'Illustration AFROBACK', null),
  ('mythe', 'mythe-nchare-yen-bamoun', 2, 'illustration', $q$https://ygkyapryramhaskfbrrt.supabase.co/storage/v1/object/public/heroes-media/images/galerie/mythologie/mythe-nchare-yen-bamoun/02.jpg$q$, $q$La course : le pagne de Koumjouom, retenu par sa sœur Mfom, le fait trébucher, et le petit Nchare fonce vers la pierre (légende bamoun publiée par A. Mounpain, illustration).$q$, $q$The race: Koumjouom's cloth, held down by his sister Mfom, makes him stumble, and little Nchare dashes toward the stone (Bamum legend published by A. Mounpain, illustration).$q$, 'Illustration AFROBACK', null),
  ('mythe', 'mythe-nchare-yen-bamoun', 5, 'illustration', $q$https://ygkyapryramhaskfbrrt.supabase.co/storage/v1/object/public/heroes-media/images/galerie/mythologie/mythe-nchare-yen-bamoun/05.jpg$q$, $q$Les sept pierres de Njimom : sous l'arbre Nshinsep, Nchare et ses sept compagnons, les Kom, proclament le pacte fondateur (tradition bamoun, illustration).$q$, $q$The seven stones of Njimom: under the Nshinsep tree, Nchare and his seven companions, the Kom, proclaim the founding pact (Bamum tradition, illustration).$q$, 'Illustration AFROBACK', null),
  ('mythe', 'mythe-ngan-medza-beti', 2, 'illustration', $q$https://ygkyapryramhaskfbrrt.supabase.co/storage/v1/object/public/heroes-media/images/galerie/mythologie/mythe-ngan-medza-beti/02.jpg$q$, $q$Le « bout de bois de l'eau » : sur le tronc surgi du fleuve, le peuple passe, lances tenues par le bout arrondi (légende beti, versions de Pierre Mebe et d'Elisabeth Belomo, illustration).$q$, $q$The "piece of wood of the water": the people cross on the trunk risen from the river, holding their spears by the rounded end (Beti legend, as told by Pierre Mebe and Elisabeth Belomo, illustration).$q$, 'Illustration AFROBACK', null),
  ('mythe', 'mythe-ngan-medza-beti', 5, 'illustration', $q$https://ygkyapryramhaskfbrrt.supabase.co/storage/v1/object/public/heroes-media/images/galerie/mythologie/mythe-ngan-medza-beti/05.jpg$q$, $q$La nuit du Yom : sous les torches de bambou, l'interdit est brisé, le tronc se révèle serpent et plonge (légende beti, illustration).$q$, $q$The night of the Yom: under the bamboo torches, the taboo is broken, the trunk reveals itself as a serpent and plunges (Beti legend, illustration).$q$, 'Illustration AFROBACK', null),
  ('mythe', 'mythe-ngan-medza-beti', 7, 'illustration', $q$https://ygkyapryramhaskfbrrt.supabase.co/storage/v1/object/public/heroes-media/images/galerie/mythologie/mythe-ngan-medza-beti/07.jpg$q$, $q$Chez les Manguissa, l'ancêtre Aso Abanda frappe le fleuve de son bâton ngékémbé : l'arc-en-ciel se couche sur l'eau et devient python (tradition rapportée par Laburthe-Tolra, illustration).$q$, $q$Among the Manguissa, the ancestor Aso Abanda strikes the river with his ngékémbé staff: the rainbow lies down on the water and becomes a python (tradition reported by Laburthe-Tolra, illustration).$q$, 'Illustration AFROBACK', null),
  ('mythe', 'mythe-sao-geants-kotoko', 2, 'illustration', $q$https://ygkyapryramhaskfbrrt.supabase.co/storage/v1/object/public/heroes-media/images/galerie/mythologie/mythe-sao-geants-kotoko/02.jpg$q$, $q$Les Sao légendaires : un géant barre la rivière de ses mains pour pêcher, des nids de rapaces dans la chevelure (légende recueillie par Marcel Griaule, 1943, illustration).$q$, $q$The legendary Sao: a giant dams the river with his hands to fish, with birds of prey nesting in his hair (legend recorded by Marcel Griaule, 1943, illustration).$q$, 'Illustration AFROBACK', null),
  ('mythe', 'mythe-sao-geants-kotoko', 5, 'illustration', $q$https://ygkyapryramhaskfbrrt.supabase.co/storage/v1/object/public/heroes-media/images/galerie/mythologie/mythe-sao-geants-kotoko/05.jpg$q$, $q$À Goulfey, la fondatrice Oulmé Machilinga plante la sagaie trouvée sur l'éminence : « J'ai trouvé de l'eau, je n'irai pas plus loin » (tradition kotoko recueillie par Annie Lebeuf, illustration).$q$, $q$At Goulfey, the founder Oulmé Machilinga plants the spear found on the rise: "I have found water, I will go no further" (Kotoko tradition recorded by Annie Lebeuf, illustration).$q$, 'Illustration AFROBACK', null);
