-- Galeries AFROBACK : mythes, illustrations générées (2026-10-16)
-- Images hébergées dans Supabase Storage : heroes-media/images/galerie/mythologie/{slug}/{ordre}.jpg (déjà envoyées).
-- Prérequis : schema-galerie.sql. Idempotent : remplace les illustrations de ces mythes.
-- Manque encore : Miengu n°6 (initiée du liengu), à ajouter quand elle sera générée.

begin;

delete from public.galerie_images where type_contenu = 'mythe' and nature = 'illustration'
  and slug in ('mythe-miengu-esprits-eau-sawa', 'mythe-nchare-yen-bamoun', 'mythe-ngan-medza-beti', 'mythe-ngog-lituba-bassa', 'mythe-sao-geants-kotoko');


commit;

select slug, nature, count(*) from public.galerie_images where type_contenu = 'mythe' group by slug, nature order by slug, nature;
